// The original PDF sets 18 and 4 as superscripts on page 14.
export const stockDecimalPrecision = agreementNodes<StockReference>(
  "(j) Decimal Precision and Truncation. Most numerical values in the smart contracts referred to herein (including token amounts, prices, multipliers, rates and voting weights) are represented as uint256 integers with 18-decimal-place precision (10¹⁸). Percentages (such as voting and approval thresholds) are stored with 4-decimal-place precision (10⁴). Precision of mathematic operations will be normalized to 18 decimals of precision (10¹⁸) and any operations exceeding that will be truncated.",
  [
    {
      start: 194,
      registered: "uint256",
      reference: { label: "unsigned 256-bit" },
    },
  ],
);

